    56→public abstract class ListControlGroups<T> extends Panel {
    57→	private static final long serialVersionUID = 7205285700113097720L;
    58→
    59→	private Map<String, AbstractControlGroup<?>> fieldComponents = new HashMap<String, AbstractControlGroup<?>>();
    60→
    61→	private Map<Class<?>, ControlGroupProvider<?>> controlGroupProviders = new HashMap<Class<?>, ControlGroupProvider<?>>();
    62→
    63→	@SuppressWarnings("rawtypes")
    64→	private final Map<Class<?>, Class<? extends AbstractControlGroup>> typesControlGroups = new HashMap<Class<?>, Class<? extends AbstractControlGroup>>();
    65→
    66→	private List<ObjectProperties> objectProperties;
    67→	private CrudifierEntitySettings entitySettings;
    68→	private Map<Class<?>, IObjectRenderer<?>> renderers;
