   123→			case COL8:
   124→				css = "col-lg-8";
   125→				break;
   126→			case COL9:
   127→				css = "col-lg-9";
   128→				break;
   129→			default:
   130→				break;
   131→			}
   132→		}
   133→		inputBox.add(AttributeModifier.append("class", css));
   134→	}
   135→	
   136→	/**
   137→	 * Copiado do FormComponent.MessageSource
   138→	 * 
   139→	 * {@link IErrorMessageSource} used for error messages against this form components.
   140→	 * 
   141→	 * @author ivaynberg
   142→	 */
   143→	protected class MessageSource implements IErrorMessageSource
   144→	{
   145→		private final Set<String> triedKeys = new LinkedHashSet<String>();
   146→
   147→		public MessageSource() {
   148→			// TODO Auto-generated constructor stub
   149→		}
   150→
   151→		/**
   152→		 * @see org.apache.wicket.validation.IErrorMessageSource#getMessage(String, java.util.Map)
   153→		 */
   154→		public String getMessage(String key, Map<String, Object> vars)
   155→		{
   156→			final AbstractControlGroup<T> formComponent = AbstractControlGroup.this;
   157→
   158→			// Use the following log4j config for detailed logging on the property resolution
   159→			// process
   160→			// log4j.logger.org.apache.wicket.resource.loader=DEBUG
   161→			// log4j.logger.org.apache.wicket.Localizer=DEBUG
   162→
   163→			final Localizer localizer = formComponent.getLocalizer();
   164→
   165→			// retrieve prefix that will be used to construct message keys
   166→			String prefix = getFormComponent().getValidatorKeyPrefix();
   167→			String message = null;
   168→
   169→			// first try the full form of key [form-component-id].[prefix].[key]
   170→			String resource = getPropertyName() + "." + prefix(prefix, key);
   171→			message = getString(localizer, resource, resourceBase);
   172→
   173→			// if not found, try a more general form (without prefix)
   174→			// [form-component-id].[key]
   175→			if (Strings.isEmpty(message) && Strings.isEmpty(prefix))
   176→			{
   177→				resource = getPropertyName() + "." + key;
   178→				message = getString(localizer, resource, resourceBase);
   179→			}
   180→
   181→			// If not found try a more general form [prefix].[key]
   182→			if (Strings.isEmpty(message))
   183→			{
   184→				resource = prefix(prefix, key);
   185→				message = getString(localizer, resource, formComponent);
   186→			}
   187→
   188→			// If not found try the most general form [key]
   189→			if (Strings.isEmpty(message))
   190→			{
   191→				// Try a variation of the resource key
   192→				message = getString(localizer, key, formComponent);
   193→			}
   194→
   195→			// convert empty string to null in case our default value of "" was
   196→			// returned from localizer
   197→			if (Strings.isEmpty(message))
   198→			{
   199→				message = null;
   200→			}
   201→			else
   202→			{
   203→				message = substitute(message, addDefaultVars(vars));
   204→			}
   205→			return message;
   206→		}
   207→
   208→		private String prefix(String prefix, String key)
   209→		{
   210→			if (!Strings.isEmpty(prefix))
   211→			{
   212→				return prefix + "." + key;
   213→			}
   214→			else
   215→			{
   216→				return key;
   217→			}
   218→		}
   219→
   220→		/**
   221→		 * 
   222→		 * @param localizer
   223→		 * @param key
   224→		 * @param component
   225→		 * @return string
   226→		 */
   227→		private String getString(Localizer localizer, String key, Component component)
   228→		{
   229→			triedKeys.add(key);
   230→
   231→			// Note: It is important that the default value of "" is
   232→			// provided to getString() not to throw a MissingResourceException or to
   233→			// return a default string like "[Warning: String ..."
   234→			return localizer.getString(key, component, "");
   235→		}
   236→
   237→		private String substitute(String string, final Map<String, Object> vars)
   238→			throws IllegalStateException
   239→		{
   240→			return new VariableInterpolator(string, Application.get()
   241→				.getResourceSettings()
   242→				.getThrowExceptionOnMissingResource())
   243→			{
   244→				private static final long serialVersionUID = 1L;
   245→
   246→				@SuppressWarnings({ "rawtypes", "unchecked" })
   247→				@Override
   248→				protected String getValue(String variableName)
   249→				{
   250→					Object value = vars.get(variableName);
   251→					if (value == null)
   252→					{
   253→						return null;
   254→					}
   255→					else
   256→					{
   257→						IConverter converter = getConverter(value.getClass());
   258→						if (converter == null)
   259→						{
   260→							return Strings.toString(value);
   261→						}
   262→						else
   263→						{
   264→							return converter.convertToString(value, getLocale());
   265→						}
   266→					}
   267→				}
   268→			}.toString();
   269→		}
   270→
   271→		/**
   272→		 * Creates a new params map that additionally contains the default input, name, label
   273→		 * parameters
   274→		 * 
   275→		 * @param params
   276→		 *            original params map
   277→		 * @return new params map
   278→		 */
   279→		private Map<String, Object> addDefaultVars(Map<String, Object> params)
   280→		{
   281→			// create and fill the new params map
   282→			final HashMap<String, Object> fullParams;
   283→			if (params == null)
   284→			{
   285→				fullParams = new HashMap<String, Object>(6);
   286→			}
   287→			else
   288→			{
   289→				fullParams = new HashMap<String, Object>(params.size() + 6);
   290→				fullParams.putAll(params);
   291→			}
   292→
   293→			// add the input param if not already present
   294→			if (!fullParams.containsKey("input"))
   295→			{
   296→				fullParams.put("input", getFormComponent().getInput());
   297→			}
   298→
   299→			// add the name param if not already present
   300→			if (!fullParams.containsKey("name"))
   301→			{
   302→				fullParams.put("name", getPropertyName());
   303→			}
   304→
   305→			// add the label param if not already present
   306→			if (!fullParams.containsKey("label"))
   307→			{
   308→				fullParams.put("label", getLabel());
   309→			}
   310→			return fullParams;
   311→		}
   312→
   313→		/**
   314→		 * @return value of label param for this form component
   315→		 */
   316→		private String getLabel()
   317→		{
   318→			String label = null;
   319→
   320→			// first try the label model ...
   321→			if (getFormComponent().getLabel() != null)
   322→			{
   323→				label = getFormComponent().getLabel().getObject();
   324→			}
   325→			// ... then try a resource of format [form-component-id] with
   326→			// default of '[form-component-id]'
   327→			if (label == null)
   328→			{
   329→
   330→				label = getFormComponent().getDefaultLabel();
   331→			}
   332→			return label;
   333→		}
   334→	}
   335→}
